 1→export interface ColumnInfo {
 2→  name: string;
 3→  type: string;
 4→}
 5→
 6→export interface TableInfo {
 7→  name: string;
 8→  columns: ColumnInfo[];
 9→  rowCount: number;
10→}
11→
12→export interface QueryResult {
13→  columns: string[];
14→  rows: Record<string, unknown>[];
15→  rowCount: number;
16→  executionTimeMs: number;
17→  resultType: 'table' | 'markdown';
18→}
19→
20→export interface ToolCallInfo {
21→  id: string;
22→  sql: string;
23→}
24→
25→export interface ToolCallResult {
26→  toolCallId: string;
27→  toolName?: string;
28→  sql: string;
29→  command?: string;
30→  toolInput?: Record<string, unknown>;
31→  columns: string[];
32→  rows: Record<string, unknown>[];
33→  rowCount: number;
34→  error?: string;
35→  output?: string;
36→  rawContent?: string;
37→}
38→
39→export interface ContentSegment {
40→  type: 'thinking' | 'tool' | 'answer';
41→  text?: string;
42→  toolResult?: ToolCallResult;
43→}
44→
45→export interface ChatMessage {
46→  id: string;
47→  role: 'user' | 'assistant';
48→  content: string;
49→  toolCalls?: ToolCallResult[];
50→  segments?: ContentSegment[];
51→  isStreaming?: boolean;
52→  currentPhase?: 'thinking' | 'answer';
53→}
