  1→import type { ToolCallResult } from '../types';
  2→import './InlineQueryResult.css';
  3→
  4→const MAX_DISPLAY_ROWS = 20;
  5→
  6→function getToolDisplayName(result: ToolCallResult): string {
  7→  const name = result.toolName || '';
  8→  if (name.includes('execute_sql')) return 'SQL Query';
  9→  if (name === 'Bash') return 'Bash';
 10→  if (name === 'Read') return 'Read File';
 11→  if (name === 'Write') return 'Write File';
 12→  if (name === 'Edit') return 'Edit File';
 13→  if (name.startsWith('mcp__')) {
 14→    // e.g. "mcp__server__tool_name" -> "tool_name"
 15→    const parts = name.split('__');
 16→    return parts[parts.length - 1] || name;
 17→  }
 18→  return name || 'Tool';
 19→}
 20→
 21→function getToolInputDisplay(result: ToolCallResult): string | null {
 22→  if (result.sql) return result.sql;
 23→  if (result.command) return result.command;
 24→  if (result.toolInput) {
 25→    const entries = Object.entries(result.toolInput);
 26→    if (entries.length === 0) return null;
 27→    // For single-value inputs, show just the value
 28→    if (entries.length === 1) return String(entries[0][1]);
 29→    return JSON.stringify(result.toolInput, null, 2);
 30→  }
 31→  return null;
 32→}
 33→
 34→function isSQL(result: ToolCallResult): boolean {
 35→  return !!result.sql && (result.toolName?.includes('execute_sql') ?? false);
 36→}
 37→
 38→export function InlineQueryResult({ result }: { result: ToolCallResult }) {
 39→  const displayName = getToolDisplayName(result);
 40→  const inputDisplay = getToolInputDisplay(result);
 41→  const isSQLTool = isSQL(result);
 42→  const hasStructuredData = result.columns.length > 0;
 43→  const displayRows = result.rows.slice(0, MAX_DISPLAY_ROWS);
 44→
 45→  // Determine border color class
 46→  let variantClass = '';
 47→  if (result.error) variantClass = 'inline-query--error';
 48→  else if (result.command) variantClass = 'inline-query--bash';
 49→  else if (!isSQLTool && !result.sql) variantClass = 'inline-query--generic';
 50→
 51→  return (
 52→    <div className={`inline-query ${variantClass}`}>
 53→      {/* Tool label */}
 54→      <div className={`inline-query__label ${isSQLTool ? 'inline-query__label--sql' : result.command ? 'inline-query__label--bash' : 'inline-query__label--generic'}`}>
 55→        {displayName}
 56→      </div>
 57→
 58→      {/* Tool input */}
 59→      {inputDisplay && (
 60→        <div className="inline-query__sql">
 61→          <code>{inputDisplay}</code>
 62→        </div>
 63→      )}
 64→
 65→      {/* Error display */}
 66→      {result.error && (
 67→        <div className="inline-query__error">{result.error}</div>
 68→      )}
 69→
 70→      {/* SQL structured results */}
 71→      {!result.error && isSQLTool && hasStructuredData && (
 72→        <>
 73→          <div className="inline-query__table-wrapper">
 74→            <table className="inline-query__table">
 75→              <thead>
 76→                <tr>
 77→                  {result.columns.map((col) => (
 78→                    <th key={col}>{col}</th>
 79→                  ))}
 80→                </tr>
 81→              </thead>
 82→              <tbody>
 83→                {displayRows.map((row, i) => (
 84→                  <tr key={i}>
 85→                    {result.columns.map((col) => (
 86→                      <td key={col}>{String(row[col] ?? '')}</td>
 87→                    ))}
 88→                  </tr>
 89→                ))}
 90→              </tbody>
 91→            </table>
 92→          </div>
 93→          <div className="inline-query__meta">
 94→            {result.rowCount} row{result.rowCount !== 1 ? 's' : ''}
 95→            {result.rowCount > MAX_DISPLAY_ROWS && ` (showing ${MAX_DISPLAY_ROWS})`}
 96→          </div>
 97→        </>
 98→      )}
 99→
100→      {/* Text output for non-SQL tools */}
101→      {!result.error && result.output && (
102→        <div className="inline-query__output">
103→          <pre>{result.output}</pre>
104→        </div>
105→      )}
106→
107→      {/* Raw content fallback */}
108→      {!result.error && !hasStructuredData && !result.output && result.rawContent && (
109→        <div className="inline-query__raw">
110→          <pre>{result.rawContent}</pre>
111→        </div>
112→      )}
113→
114→      {/* Pending state */}
115→      {!result.error && !hasStructuredData && !result.output && !result.rawContent && inputDisplay && (
116→        <div className="inline-query__meta">Executing...</div>
117→      )}
118→    </div>
119→  );
120→}
